export default JSON.parse(
  "{\n  \"workId\": \"mo-zi\",\n  \"chapter\": {\n    \"id\": \"mo-zi_ch-28\",\n    \"workId\": \"mo-zi\",\n    \"order\": 28,\n    \"title\": \"天志下\",\n    \"difficulty\": 5,\n    \"estimatedMinutes\": 11,\n    \"passageIds\": [\n      \"mo-zi_ch-28_p-1\",\n      \"mo-zi_ch-28_p-2\",\n      \"mo-zi_ch-28_p-3\",\n      \"mo-zi_ch-28_p-4\",\n      \"mo-zi_ch-28_p-5\",\n      \"mo-zi_ch-28_p-6\",\n      \"mo-zi_ch-28_p-7\",\n      \"mo-zi_ch-28_p-8\"\n    ],\n    \"tags\": [\n      \"墨家\",\n      \"墨子\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"mo-zi_ch-28_p-1\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"order\": 1,\n      \"canonicalText\": \"子墨子言曰：「天下之所以亂者，其說將何哉？則是天下士君子，皆明於小而不明於大。何以知其明於小不明於大也？以其不明於天之意也。何以知其不明於天之意也？以處人之家者知之。今人處若家得罪，將猶有異家所，以避逃之者，然且父以戒子，兄以戒弟，曰：『戒之慎之，處人之家，不戒不慎之，而有處人之國者乎？』今人處若國得罪，將猶有異國所，以避逃之者矣，然且父以戒子，兄以戒弟，曰：『戒之慎之，處人之國者，不可不戒慎也！』今人皆處天下而事天，得罪於天，將無所以避逃之者矣。然而莫知以相極戒也，吾以此知大物則不知者也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-28_p-1_s-1\",\n        \"mo-zi_ch-28_p-1_s-2\",\n        \"mo-zi_ch-28_p-1_s-3\",\n        \"mo-zi_ch-28_p-1_s-4\",\n        \"mo-zi_ch-28_p-1_s-5\",\n        \"mo-zi_ch-28_p-1_s-6\",\n        \"mo-zi_ch-28_p-1_s-7\",\n        \"mo-zi_ch-28_p-1_s-8\",\n        \"mo-zi_ch-28_p-1_s-9\",\n        \"mo-zi_ch-28_p-1_s-10\",\n        \"mo-zi_ch-28_p-1_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"墨子說道：「天下的社會秩序之所以陷入動盪混亂，究其根本原因究竟是什麼呢？那是因為天下的士人君子，都僅僅明瞭細微微小的小節道理，卻對關係全局的根本大事懵然無知。憑藉什麼知道他們明於小事而不明大事呢？憑他們不明曉上天的至高意旨就可以知道。又憑藉什麼知道他們不明白天意呢？從人們寄居在別人家中的情形就可以省察出來。如今一個人在某一家中居留，如果不慎得罪了家主，尚且還可以逃往別的家族宅第去躲避藏匿；然而即便如此，父親依然嚴肅告誡兒子，兄長依然叮囑弟弟說：『務必警惕謹慎啊！寄居在別人家中，若不加警惕戒備，難道還能容身安處嗎？』如今一個人在某一個國家之中，得罪了國君，尚且還可以流亡逃奔到別的國家去躲避求生；即便如此，做父親的仍警戒其子，做兄長的仍告誡其弟說：『務必警惕謹慎啊！居留在別人的邦國，不可不萬分戒懼謹慎！』然而如今全天下的人無一不是生活在天地之間而受上天覆育主宰，一旦得罪了至高無上的上天，將再也沒有任何退路與別處可以躲避藏匿了！然而世人卻全不知道要以此至高的大罪互相鄭重告誡警惕，我因此確知世人對於關係根本性命的天下大事反而是愚昧無知的。」\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志下〉。墨子學派以兼愛天下為宗，開篇「子墨子言曰：「天下之所以亂者，其說將何哉」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「言」、「天」、「下」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「子墨子言曰天下之所以亂者其說將何哉則是天下士君子」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「則是天下士君子，皆明於小而不明於大」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"order\": 2,\n      \"canonicalText\": \"是故子墨子言曰：「戒之慎之，必為天之所欲，而去天之所惡。曰天之所欲者何也？所惡者何也？天欲義而惡其不義者也。何以知其然也？曰義者正也。何以知義之為正也？天下有義則治，無義則亂，我以此知義之為正也。然而正者，無自下正上者，必自上正下。是故庶人不得次己而為正，有士正之；士不得次己而為正，有大夫正之；大夫不得次己而為正，有諸侯正之；諸侯不得次己而為正，有三公正之；三公不得次己而為正，有天子正之；天子不得次己而為政，有天正之。今天下之士君子，皆明於天子之正天下也，而不明於天之正天子也。是故古者聖人，明以此說人曰：『天子有善，天能賞之；天子有過，天能罰之。』天子賞罰不當，聽獄不中，天下疾病禍祟，霜露不時，天子必且犓豢其牛羊犬彘，絜為粢盛酒醴，以禱祠祈福於天，我未嘗聞天之禱祈福於天子也，吾以此知天之貴且知於天子也。是故義者不自愚且賤者出，必自貴且知者出。曰誰為貴？天為貴。誰為知？天為知。然則義果自天出也。今天下之士君子之慾為義者，則不可不順天之意矣。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-28_p-2_s-1\",\n        \"mo-zi_ch-28_p-2_s-2\",\n        \"mo-zi_ch-28_p-2_s-3\",\n        \"mo-zi_ch-28_p-2_s-4\",\n        \"mo-zi_ch-28_p-2_s-5\",\n        \"mo-zi_ch-28_p-2_s-6\",\n        \"mo-zi_ch-28_p-2_s-7\",\n        \"mo-zi_ch-28_p-2_s-8\",\n        \"mo-zi_ch-28_p-2_s-9\",\n        \"mo-zi_ch-28_p-2_s-10\",\n        \"mo-zi_ch-28_p-2_s-11\",\n        \"mo-zi_ch-28_p-2_s-12\",\n        \"mo-zi_ch-28_p-2_s-13\",\n        \"mo-zi_ch-28_p-2_s-14\",\n        \"mo-zi_ch-28_p-2_s-15\",\n        \"mo-zi_ch-28_p-2_s-16\",\n        \"mo-zi_ch-28_p-2_s-17\",\n        \"mo-zi_ch-28_p-2_s-18\",\n        \"mo-zi_ch-28_p-2_s-19\",\n        \"mo-zi_ch-28_p-2_s-20\",\n        \"mo-zi_ch-28_p-2_s-21\",\n        \"mo-zi_ch-28_p-2_s-22\",\n        \"mo-zi_ch-28_p-2_s-23\",\n        \"mo-zi_ch-28_p-2_s-24\",\n        \"mo-zi_ch-28_p-2_s-25\",\n        \"mo-zi_ch-28_p-2_s-26\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"因此墨子語重心長地告誡說：「務必萬分戒惕、謹慎行事，一定要力行上天所期許的大道，堅決革除上天所厭惡的罪愆！那麼上天所企盼的究竟是什麼？上天所憎惡的又是什麼呢？上天所希冀的是公平正義，而深惡痛絕的是背信棄義。憑藉什麼知道是這樣呢？因為義的本質就是公正的匡正與救正。又憑何知道義就是公正之正呢？天下擁有公義則天下太平大治，喪失公義則四海混亂動盪，我憑藉這一顛撲不破的歷史規律知道義正是至高的公正。然而這種公正的匡正，絕不可能由處於下位的人去矯正統治上位的人，而必然是由地位至尊的上位者去匡正處於下位的人。因此平民庶人不得隨意自行立規作法以稱公正，而由士人來匡正他；士人不得任憑私意自行制定規範，而由大夫來匡正他；大夫不得各行其是隨意定準，而由諸侯來匡正他；諸侯不得僭越自專建立標準，而由朝廷三公來匡正他；三公不得以私心自為標準，而由天子來匡正他；而天子同樣不得任意妄為自命標準，至高無上的上天自然會居高臨下匡正天子！如今普天下的士人君子，都只清楚天子可以規範匡正普天下的臣民，卻偏偏不明白上天隨時都在監察匡正天子自身的德行。所以古代的聖哲先賢，明白無誤地用這些道理曉諭世人說：『天子若有善德嘉行，上天必定會降福賞賜他；天子若有罪過失德，上天必定會降災懲罰他。』倘若天子行賞罰不公允不適度，審理刑獄不中正偏私，天下便會爆發疾病瘟疫、凶荒災禍，霜露雨雪違背四時節候而降，此時天子必定惶恐憂懼，親自餵養肥壯牛羊豬狗等各類牲畜，潔淨蒸備黍稷酒醴祭品，向天帝祈禱禳災、乞求寬宥降福；我卻從未聽說過上天會反過來向人間天子禱告祈求賜福的。我因此真切地明白：上天的尊貴與智慧，遠遠凌駕於人間天子之上！所以真正的公義法度絕不可能從愚昧卑下的人那裡創生，而必然是從全知全尊的主宰那裡流出。那麼究竟誰最尊貴？唯有上天至尊無上！誰最富智慧？唯有上天全知至明！既然如此，那麼人間至高的義理果然是發源自上天。當今天下的士人君子若真心想要實踐公義，那就絕不可不順從上天的旨意！\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志下〉。墨子學派以兼愛天下為宗，開篇「是故子墨子言曰：「戒之慎之，必為天之所欲，而去天之所惡」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「是」、「言」、「戒」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「是故子墨子言曰戒之慎之必為天之所欲而去天之所惡曰」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「曰天之所欲者何也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-3\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"order\": 3,\n      \"canonicalText\": \"曰順天之意何若？曰兼愛天下之人。何以知兼愛天下之人也？以兼而食之也。何以知其兼而食之也？自古及今無有遠靈孤夷之國，皆犓豢其牛羊犬彘，絜為粢盛酒醴，以敬祭祀上帝山川鬼神，以此知兼而食之也。苟兼而食焉，必兼而愛之。譬之若楚、越之君，今是楚王食於楚之四境之內，故愛楚之人；越王食於越，故愛越之人。今天兼天下而食焉，我以此知其兼愛天下之人也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-28_p-3_s-1\",\n        \"mo-zi_ch-28_p-3_s-2\",\n        \"mo-zi_ch-28_p-3_s-3\",\n        \"mo-zi_ch-28_p-3_s-4\",\n        \"mo-zi_ch-28_p-3_s-5\",\n        \"mo-zi_ch-28_p-3_s-6\",\n        \"mo-zi_ch-28_p-3_s-7\",\n        \"mo-zi_ch-28_p-3_s-8\",\n        \"mo-zi_ch-28_p-3_s-9\",\n        \"mo-zi_ch-28_p-3_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說道：順天的意何若？說道：天下兼相愛、交相利天下的人。何以知天下兼相愛、交相利天下的人啊？以兼而且食的啊。何以知他的兼而且食的啊？自古及今無有遠靈孤夷的國，皆犓豢他的牛羊犬彘，絜為粢盛酒醴，以敬祭祀上帝山川鬼神，以此知兼而且食的啊。苟兼而且食焉，必兼而且愛的。譬的若楚、越的君，今是楚王食於楚的四境的內，所以愛楚的人；越王食於越，所以愛越的人。今天兼天下而且食焉，我以此知他的天下兼相愛、交相利天下的人啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志下〉。墨子學派以兼愛天下為宗，開篇「曰順天之意何若」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「順」、「天」、「意」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「曰順天之意何若曰兼愛天下之人何以知兼愛天下之人也」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「曰兼愛天下之人」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"order\": 4,\n      \"canonicalText\": \"且天之愛百姓也，不盡物而止矣。今天下之國，粒食之民，殺一不辜者，必有一不祥。曰誰殺不辜？曰人也。孰予之不祥？曰天也。若天之中實不愛此民也，何故而人有殺不辜，而天予之不祥哉？且天之愛百姓厚矣，天之愛百姓別矣，既可得而知也。何以知天之愛百姓也？吾以賢者之必賞善罰暴也。何以知賢者之必賞善罰暴也？吾以昔者三代之聖王知之。故昔也三代之聖王堯舜禹湯文武之兼愛天下也，從而利之，移其百姓之意焉，率以敬上帝山川鬼神，天以為從其所愛而愛之，從其所利而利之，於是加其賞焉，使之處上位，立為天子以法也，名之曰『聖人』，以此知其賞善之證。是故昔也三代之暴王桀紂幽厲之兼惡天下也，從而賊之，移其百姓之意焉，率以詬侮上帝山川鬼神，天以為不從其所愛而惡之，不從其所利而賊之，於是加其罰焉，使之父子離散，國家滅亡，抎失社稷，憂以及其身。是以天下之庶民屬而毀之，業萬世子孫繼嗣，毀之者不廢也，名之曰『暴王』，以此知其罰暴之證。今天下之士君子，欲為義者，則不可不順天之意矣。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-28_p-4_s-1\",\n        \"mo-zi_ch-28_p-4_s-2\",\n        \"mo-zi_ch-28_p-4_s-3\",\n        \"mo-zi_ch-28_p-4_s-4\",\n        \"mo-zi_ch-28_p-4_s-5\",\n        \"mo-zi_ch-28_p-4_s-6\",\n        \"mo-zi_ch-28_p-4_s-7\",\n        \"mo-zi_ch-28_p-4_s-8\",\n        \"mo-zi_ch-28_p-4_s-9\",\n        \"mo-zi_ch-28_p-4_s-10\",\n        \"mo-zi_ch-28_p-4_s-11\",\n        \"mo-zi_ch-28_p-4_s-12\",\n        \"mo-zi_ch-28_p-4_s-13\",\n        \"mo-zi_ch-28_p-4_s-14\",\n        \"mo-zi_ch-28_p-4_s-15\",\n        \"mo-zi_ch-28_p-4_s-16\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"況且上天愛護天下的黎民百姓，絕不是草率敷衍、留有保留的。如今普天下的各個邦國，凡是依靠穀物粒食繁衍生息的人民，只要有人殺害了一個無辜的生命，上天就必定會降下一件凶禍災祥給予警示。請問是誰殺害了無辜者呢？是人殺害了人。又是誰降下了凶殃怪異呢？正是上天降下的。假若上天的內心深處當真不愛惜這些民眾，何以世間一旦有人濫殺無辜，上天就會立時降臨凶異進行警告與懲戒呢？可見上天愛護萬民是何等深厚，上天對民眾的關懷眷顧是何等真切分明，這完全是切實可證而人人皆可得知的。又憑藉什麼知道上天如此厚愛百姓呢？我是從賢明的聖王必然賞善罰暴的歷史事實中體認出來的。又何以知道賢明的統治者必能賞善罰暴呢？我是從昔日三代的聖王典範中洞察確認的。昔日三代的聖王堯、舜、禹、商湯、周文王與周武王，他們平等博愛普天下的百姓，進而為萬民廣興福利，引導歸正天下百姓的心意，率領臣民共同敬奉上帝山川鬼神；上天認定聖王順應了天意所愛的民眾而去厚愛他們，依從了天意所要利益的蒼生而去造福他們，於是降下無上厚賞，讓他們身居尊崇首位，立為天下之主的天子以垂範萬方，尊奉他們的美號為『至聖先王』，這就是上天賞賜善德的真憑實據。昔日三代的暴君夏桀、商紂、周幽王與周厲王，他們普遍憎恨厭惡普天下的百姓，進而肆意殘害生靈，扭曲敗壞臣民的心智良知，率領天下人謾罵侮辱上帝、褻瀆山川鬼神；上天認定暴君違背了天意所愛的萬民而去殘害荼毒他們，背離了天意所要利益的蒼生而大肆劫掠虐殺，於是降下嚴厲懲罰，使他們父子骨肉離散，社稷邦國灰飛煙滅，宗廟傾覆喪亡，大禍禍延自身性命。因此天下的萬民世代相傳同聲唾罵痛斥他們，哪怕歷經萬世子孫繼承延綿，人們對他們的斥責唾棄也永不廢絕，將他們永遠釘在恥辱柱上稱為『無道暴君』，這就是上天懲治暴虐的確鑿鐵證。所以當今天下的士人君子若真心想行義立身，就絕不可不順從上天的意旨啊！\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志下〉。墨子學派以兼愛天下為宗，開篇「且天之愛百姓也，不盡物而止矣」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「且」、「天」、「愛」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「且天之愛百姓也不盡物而止矣今天下之國粒食之民殺一」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「今天下之國，粒食之民，殺一不辜者，必有一不祥」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"order\": 5,\n      \"canonicalText\": \"曰順天之意者，兼也；反天之意者，別也。兼之為道也，義正；別之為道也，力正。曰義正者何若？曰大不攻小也，強不侮弱也，眾不賊寡也，詐不欺愚也，貴不傲賤也，富不驕貧也，壯不奪老也。是以天下之庶國，莫以水火毒藥兵刃以相害也。若事上利天，中利鬼，下利人，三利而無所不利，是謂天德。故凡從事此者，聖知也，仁義也，忠惠也，慈孝也，是故聚斂天下之善名而加之。是其故何也？則順天之意也。曰力正者何若？曰大則攻小也，強則侮弱也，眾則賊寡也，詐則欺愚也，貴則傲賤也，富則驕貧也，壯則奪老也。是以天下之庶國，方以水火毒藥兵刃以相賊害也。若事上不利天，中不利鬼，下不利人，三不利而無所利，是謂天賊。故凡從事此者，寇亂也，盜賊也，不仁不義，不忠不惠，不慈不孝，是故聚斂天下之惡名而加之。是其故何也？則反天之意也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-28_p-5_s-1\",\n        \"mo-zi_ch-28_p-5_s-2\",\n        \"mo-zi_ch-28_p-5_s-3\",\n        \"mo-zi_ch-28_p-5_s-4\",\n        \"mo-zi_ch-28_p-5_s-5\",\n        \"mo-zi_ch-28_p-5_s-6\",\n        \"mo-zi_ch-28_p-5_s-7\",\n        \"mo-zi_ch-28_p-5_s-8\",\n        \"mo-zi_ch-28_p-5_s-9\",\n        \"mo-zi_ch-28_p-5_s-10\",\n        \"mo-zi_ch-28_p-5_s-11\",\n        \"mo-zi_ch-28_p-5_s-12\",\n        \"mo-zi_ch-28_p-5_s-13\",\n        \"mo-zi_ch-28_p-5_s-14\",\n        \"mo-zi_ch-28_p-5_s-15\",\n        \"mo-zi_ch-28_p-5_s-16\",\n        \"mo-zi_ch-28_p-5_s-17\",\n        \"mo-zi_ch-28_p-5_s-18\",\n        \"mo-zi_ch-28_p-5_s-19\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以說：順應上天心意的大道，就是兼相愛；違逆上天心意的謬誤，就是自私劃界的偏愛。兼愛的推行法則，是以道德義理來匡正天下；偏愛的行事法則，是以暴力強權來威逼天下。那麼什麼是以義理匡正呢？那就是大國絕不攻伐小國，強族絕不凌辱弱族，人口眾多者絕不殘害寡少者，奸狡巧詐者絕不欺騙愚訥者，地位高貴者絕不傲視卑賤者，財富豐足者絕不鄙視貧困者，年富力壯者絕不強奪孤苦老邁者的資財。正因如此，普天下的所有邦國，沒有誰會使用洪水烈火、猛烈毒藥或是兵刃利刃去互相殘殺加害。這樣的事情，對上利於敬天，居中利於祭神，對下利於濟民，三種利益齊備而毫無害處，這就稱作體現了上天的純粹美德。因此凡是奉行兼愛的人，就是具備大智大慧的聖哲，是仁人義士，是忠臣惠主，是慈父孝子；普天下所有崇高善良的讚美名號都會歸聚加諸於他的身上。這究竟是什麼緣故呢？正是因為他完完全全順應了上天的旨意！那麼所謂以暴力強權來威逼，又是什麼情況呢？那就是大國動輒發兵進攻小國，強橫者肆意凌辱孱弱者，人多勢眾者殘酷迫害寡少人眾，狡猾欺詐者大肆蒙蔽愚鈍淳樸者，尊貴顯赫者傲慢踐踏卑賤平民，家財萬貫者驕奢凌蔑貧苦赤貧，年輕力壯者野蠻強搶年邁體弱者的口糧。正因如此，普天下的萬千邦國，競相藉由水淹火燒、劇毒暗算與刀槍兵革來相互殘害屠殺。這樣的事情，對上觸怒上天，居中褻瀆鬼神，對下殘害無辜萬民，三方毫無利益而處處帶來禍害，這就稱作戕害天道的國之大賊。因此凡是推行這種強暴做法的人，就是禍國殃民的寇讎逆賊，是不仁不義的惡徒，是不忠不慈的敗類，是忤逆不孝的罪人；普天下所有醜惡可恥的罵名都會集中傾瀉到他的頭上。這究竟又是什麼原因呢？正是因為他徹底逆悖抗拒了上天至仁至善的神聖意旨！」\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志下〉。墨子學派以兼愛天下為宗，開篇「曰順天之意者，兼也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「順」、「天」、「意」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「曰順天之意者兼也反天之意者別也兼之為道也義正別之」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「反天之意者，別也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"order\": 6,\n      \"canonicalText\": \"故子墨子置立天之，以為儀法，若輪人之有規，匠人之有矩也。今輪人以規，匠人以矩，以此知方圜之別矣。是故子墨子置立天之，以為儀法。吾以此知天下之士君子之去義遠也。何以知天下之士君子之去義遠也？今知氏大國之君寬者然曰：「吾處大國而不攻小國，吾何以為大哉！」是以差論蚤牙之士，比列其舟車之卒，以攻伐無罪之國，入其邊境，刈其禾稼，斬其樹木，殘其城郭，以湮其溝池，焚燒其祖廟，攘殺其犧牷，民之格者，則剄殺之，不格者，則係操而歸，丈夫以為僕圉胥靡，婦人以為舂酋。則夫好攻伐之君，不知此為不仁義，以告四鄰諸侯曰：「吾攻國覆軍，殺將若干人矣。」其鄰國之君亦不知此為不仁義也，有具其皮幣，發其總處，使人饗賀焉。則夫好攻伐之君，有重不知此為不仁不義也，有書之竹帛，藏之府庫。為人後子者，必且欲順其先君之行，曰：「何不當發吾府庫，視吾先君之法美。」必不曰文、武之為正者若此矣，曰吾攻國覆軍殺將若干人矣。則夫好攻伐之君，不知此為不仁不義也，其鄰國之君不知此為不仁不義也，是以攻伐世世而不已者，此吾所謂大物則不知也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-28_p-6_s-1\",\n        \"mo-zi_ch-28_p-6_s-2\",\n        \"mo-zi_ch-28_p-6_s-3\",\n        \"mo-zi_ch-28_p-6_s-4\",\n        \"mo-zi_ch-28_p-6_s-5\",\n        \"mo-zi_ch-28_p-6_s-6\",\n        \"mo-zi_ch-28_p-6_s-7\",\n        \"mo-zi_ch-28_p-6_s-8\",\n        \"mo-zi_ch-28_p-6_s-9\",\n        \"mo-zi_ch-28_p-6_s-10\",\n        \"mo-zi_ch-28_p-6_s-11\",\n        \"mo-zi_ch-28_p-6_s-12\",\n        \"mo-zi_ch-28_p-6_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"因此墨子確立並樹立天之意旨，作為世人行事的根本儀表與法則，這就好比製作車輪的工匠身邊備有圓規，建造房屋的木工匠人手中拿著曲尺一樣。如今車匠憑藉圓規，木匠憑藉曲尺，以此便能確鑿分明地知曉方與圓的客觀差別。因此墨子確立天之意旨作為天下法度。我藉此便能明察普天下的士人君子，如今距離真正的仁義之道是何等遙遠！憑藉什麼知道天下的士人君子離真正的正義極其遙遠呢？如今那些自命聰明的大國君主，一個個寬舒自得、傲慢自大地說：『我們身處堂堂大國，如果不去征伐掠奪弱小邦國，我們又憑什麼能顯示出國家的強大威嚴呢！』於是他們大肆挑選操練勇猛如爪牙的精銳甲士，陳列整編他們的戰船與戰車部隊，興無名之師去殘酷攻打毫無罪過的小國弱邦，長驅直入敵國邊境，收割焚燬百姓的莊稼田禾，砍伐破壞世代培植的果樹森林，毀壞平毀堅固的城池城郭，填塞阻斷防禦的護城壕溝，放火焚燒歷代祖先的宗廟祭所，強搶屠宰祭神祭祖的犧牲牛羊；遇到敢於抵抗防衛的敵國軍民，就毫不留情地斬首屠殺；遇到不敢抵抗的無辜百姓，就用繩索捆綁押解回國，將成年男子強充為放牧奴隸與服苦役的囚徒，將婦女強行掠奪為舂米釀酒的婢妾。而那些沉溺於兼併攻伐的霸道國君，竟絲毫不知道這種殘暴行徑是徹頭徹尾的不仁不義，反而得意洋洋地通告四鄰諸侯宣稱：『我軍攻破了某個邦國、覆滅了某支敵軍，陣斬敵軍將領若干人！』更令人扼腕的是，鄰近各國的君主同樣昏聵懵懂，絲毫意識不到這是不仁不義的滔天罪行，反而備辦精緻的毛皮幣帛，派出盛大朝聘使節，派人設宴獻禮慶賀其兼併勝利！而那個窮兵黷武的攻伐之君，就更加自鳴得意，愈發不知此舉是嚴重的不仁不義，甚至命史官鄭重將戰績書寫在竹簡絲帛之上，當作家族榮耀深藏於國家府庫之中。其後世繼承王位的子孫，為了效仿效順先君的所謂豐功偉績，便說：『何不快點打開我們宗廟的府庫，瞻仰學習我們先君留下來的法度美名！』他們絕不會宣揚周文王、周武王施仁行義的正道政績，卻只會津津樂道於『我們先君攻滅了某個鄰邦、全殲了某國軍隊、斬殺了敵將幾十人』。由此可見，好戰侵伐的君王不知道這是不仁不義，周邊鄰國的國君也盲目附和不知是不仁不義，導致殘酷的兼併戰爭世世代代循環不休，生靈塗炭永無寧日，這就是我所說的世人對關係生民安危的根本大義反而盲目不知啊！\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志下〉。墨子學派以兼愛天下為宗，開篇「故子墨子置立天之，以為儀法，若輪人之有規，匠人之有矩也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「置」、「立」、「天」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「故子墨子置立天之以為儀法若輪人之有規匠人之有矩也」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「今輪人以規，匠人以矩，以此知方圜之別矣」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"order\": 7,\n      \"canonicalText\": \"所謂小物則知之者何若？今有人於此，入人之場園，取人之桃李瓜薑者，上得且罰之，眾聞則非之，是何也？曰不與其勞，獲其實，已非其有所取之故，而況有踰於人之牆垣，抯格人之子女者乎？與角人之府庫，竊人之金玉蚤絫者乎？與踰人之欄牢，竊人之牛馬者乎？而況有殺一不辜人乎？今王公大人之為政也，自殺一不辜人者；踰人之牆垣，抯格人之子女者；與角人之府庫，竊人之金玉蚤絫者乎；與踰人之欄牢，竊人之牛馬者；與入人之場園，竊人之桃李瓜薑者，今王公大人之加罰此也，雖古之堯舜禹湯文武之為政，亦無以異此矣。今天下之諸侯，將猶皆侵凌攻伐兼併，此為殺一不辜人者，數千萬矣；此為踰人之牆垣，格人之子女者，與角人府庫，竊人金玉蚤絫者，數千萬矣；踰人之欄牢，竊人之牛馬者，與入人之場園，竊人之桃李瓜薑者，數千萬矣，而自曰義也。故子墨子言曰：「是蕡我者，則豈有以異是蕡黑白甘苦之辯者哉！今有人於此，少而示之黑謂之黑，多示之黑謂白，必曰吾目亂，不知黑白之別。今有人於此，能少嘗之甘謂甘，多嘗謂苦，必曰吾口亂，不知其甘苦之味。今王公大人之政也，或殺人，其國家禁之，此蚤越有能多殺其鄰國之人，因以為文義，此豈有異蕡白黑、甘苦之別者哉？」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-28_p-7_s-1\",\n        \"mo-zi_ch-28_p-7_s-2\",\n        \"mo-zi_ch-28_p-7_s-3\",\n        \"mo-zi_ch-28_p-7_s-4\",\n        \"mo-zi_ch-28_p-7_s-5\",\n        \"mo-zi_ch-28_p-7_s-6\",\n        \"mo-zi_ch-28_p-7_s-7\",\n        \"mo-zi_ch-28_p-7_s-8\",\n        \"mo-zi_ch-28_p-7_s-9\",\n        \"mo-zi_ch-28_p-7_s-10\",\n        \"mo-zi_ch-28_p-7_s-11\",\n        \"mo-zi_ch-28_p-7_s-12\",\n        \"mo-zi_ch-28_p-7_s-13\",\n        \"mo-zi_ch-28_p-7_s-14\",\n        \"mo-zi_ch-28_p-7_s-15\",\n        \"mo-zi_ch-28_p-7_s-16\",\n        \"mo-zi_ch-28_p-7_s-17\",\n        \"mo-zi_ch-28_p-7_s-18\",\n        \"mo-zi_ch-28_p-7_s-19\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"那麼世人所謂對微細小事清清楚楚，又是什麼情況呢？如今假定有個人在這裡，偷偷溜進別人的菜園果園，偷竊了別人少許的桃李果實、瓜果生薑，官府長吏一旦抓捕到他，必定會依法懲處治罪，民眾聽聞此事也都會眾口一詞地非難唾棄他。這究竟是為什麼呢？因為他不勞而獲，嚴重損害侵奪了他人的勞動利益。倘若此人進一步偷竊別人的雞鴨犬豕，他的罪過必然遠大於偷摘瓜果，這是因為他對他人利益的損害更加深重；倘若再進一步跨進別人的馬廄牛欄，偷牽別人的牛馬，其罪過又遠遠大於偷竊雞犬，這也是因為他侵奪損害別人的資財益發巨大。如果一個人殘忍地殺害無辜路人，強行剝下他的衣物皮裘，搶奪他的戈劍兵器，其罪過必然十倍於偷牽牛馬，這是因為他對別人生存權益的侵害達到了頂點。天下的士人君子遇到這些案件，全都明白其是非黑白，紛紛口誅筆伐，稱其為罪犯賊寇，長吏也依據法典對其嚴加懲罰判刑。可見，侵犯損害別人的程度愈嚴重，其行為的不仁不義就愈加深重，其罪孽也就愈發無可饒恕，這些微末小事世人無不辨別得一清二楚。然而一到了最極端、最嚴重的大不仁大不義——舉兵攻伐無辜的國家、殘殺成千上萬的生靈、劫奪萬民的土地城邑，天下的士人君子不但不加非難抵制，反而大加讚揚、隨聲附和，甚至載入史冊奉為至高榮譽！這豈不是在是非善惡的最關鍵處全盤顛倒昏亂嗎？世人於微末小惡尚能嚴詞譴責，面對滔天大罪卻擊節讚賞，這就是我所揭露的『明於小而暗於大、知小事而昧於大道』的天下根本病灶！\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志下〉。墨子學派以兼愛天下為宗，開篇「所謂小物則知之者何若」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「謂」、「小」、「物」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「所謂小物則知之者何若今有人於此入人之場園取人之桃」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「今有人於此，入人之場園，取人之桃李瓜薑者，上得且罰之，眾聞則非之，是何也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-8\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"order\": 8,\n      \"canonicalText\": \"故子墨子置天之，以為儀法。非獨子墨子以天之志為法也，於先王之書大夏之道之然：「帝謂文王，予懷而明德，毋大聲以色，毋長夏以革，不識不知，順帝之則。」此誥文王之以天志為法也，而順帝之則也。且今天下之士君子，中實將欲為仁義，求為上士，上欲中聖王之道，下欲中國家百姓之利者，當天之志，而不可不察也。天之志者，義之經也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-28_p-8_s-1\",\n        \"mo-zi_ch-28_p-8_s-2\",\n        \"mo-zi_ch-28_p-8_s-3\",\n        \"mo-zi_ch-28_p-8_s-4\",\n        \"mo-zi_ch-28_p-8_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以子墨子置天的，以為儀法。絕不是獨子墨子以天的志為法啊，於先王的書大夏的道的然：帝謂文王，予懷而且明德，毋大聲以色，毋長夏以革，不識不知，順帝的則。此誥文王的以順應上天博愛之天志準則為法啊，而且順帝的則啊。且今天下的士君子，中客觀實體將欲為仁義，求為上士，上欲中聖王的道，下欲中國家百姓的利的人，當天的志，而且不可不察啊。天的志的人，義的經啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈天志下〉。墨子學派以兼愛天下為宗，開篇「故子墨子置天之，以為儀法」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「置」、「天」、「為」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「故子墨子置天之以為儀法非獨子墨子以天之志為法也於」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「非獨子墨子以天之志為法也，於先王之書大夏之道之然：「帝謂文王，予懷而明德，毋大聲以色，毋長夏以革，不識不知，順帝之則」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"mo-zi_ch-28_p-1_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"子墨子言曰：「天下之所以亂者，其說將何哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-1_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"則是天下士君子，皆明於小而不明於大。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-1_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"何以知其明於小不明於大也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-1_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"以其不明於天之意也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-1_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"何以知其不明於天之意也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-1_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"以處人之家者知之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-1_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"今人處若家得罪，將猶有異家所，以避逃之者，然且父以戒子，兄以戒弟，曰：『戒之慎之，處人之家，不戒不慎之，而有處人之國者乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-1_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"』今人處若國得罪，將猶有異國所，以避逃之者矣，然且父以戒子，兄以戒弟，曰：『戒之慎之，處人之國者，不可不戒慎也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-1_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"』今人皆處天下而事天，得罪於天，將無所以避逃之者矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-1_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"然而莫知以相極戒也，吾以此知大物則不知者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-1_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-1\",\n      \"order\": 11,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"是故子墨子言曰：「戒之慎之，必為天之所欲，而去天之所惡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"曰天之所欲者何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"所惡者何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"天欲義而惡其不義者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"何以知其然也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"曰義者正也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"何以知義之為正也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"天下有義則治，無義則亂，我以此知義之為正也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 9,\n      \"canonicalText\": \"然而正者，無自下正上者，必自上正下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 10,\n      \"canonicalText\": \"是故庶人不得次己而為正，有士正之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 11,\n      \"canonicalText\": \"士不得次己而為正，有大夫正之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 12,\n      \"canonicalText\": \"大夫不得次己而為正，有諸侯正之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 13,\n      \"canonicalText\": \"諸侯不得次己而為正，有三公正之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 14,\n      \"canonicalText\": \"三公不得次己而為正，有天子正之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 15,\n      \"canonicalText\": \"天子不得次己而為政，有天正之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-16\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 16,\n      \"canonicalText\": \"今天下之士君子，皆明於天子之正天下也，而不明於天之正天子也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-17\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 17,\n      \"canonicalText\": \"是故古者聖人，明以此說人曰：『天子有善，天能賞之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-18\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 18,\n      \"canonicalText\": \"天子有過，天能罰之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-19\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 19,\n      \"canonicalText\": \"』天子賞罰不當，聽獄不中，天下疾病禍祟，霜露不時，天子必且犓豢其牛羊犬彘，絜為粢盛酒醴，以禱祠祈福於天，我未嘗聞天之禱祈福於天子也，吾以此知天之貴且知於天子也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-20\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 20,\n      \"canonicalText\": \"是故義者不自愚且賤者出，必自貴且知者出。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-21\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 21,\n      \"canonicalText\": \"曰誰為貴？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-22\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 22,\n      \"canonicalText\": \"天為貴。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-23\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 23,\n      \"canonicalText\": \"誰為知？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-24\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 24,\n      \"canonicalText\": \"天為知。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-25\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 25,\n      \"canonicalText\": \"然則義果自天出也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-2_s-26\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-2\",\n      \"order\": 26,\n      \"canonicalText\": \"今天下之士君子之慾為義者，則不可不順天之意矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-3_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"曰順天之意何若？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-3_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"曰兼愛天下之人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-3_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"何以知兼愛天下之人也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-3_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"以兼而食之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-3_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"何以知其兼而食之也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-3_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"自古及今無有遠靈孤夷之國，皆犓豢其牛羊犬彘，絜為粢盛酒醴，以敬祭祀上帝山川鬼神，以此知兼而食之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-3_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"苟兼而食焉，必兼而愛之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-3_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"譬之若楚、越之君，今是楚王食於楚之四境之內，故愛楚之人；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-3_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"越王食於越，故愛越之人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-3_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-3\",\n      \"order\": 10,\n      \"canonicalText\": \"今天兼天下而食焉，我以此知其兼愛天下之人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"且天之愛百姓也，不盡物而止矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"今天下之國，粒食之民，殺一不辜者，必有一不祥。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"曰誰殺不辜？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"曰人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"孰予之不祥？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"曰天也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"若天之中實不愛此民也，何故而人有殺不辜，而天予之不祥哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"且天之愛百姓厚矣，天之愛百姓別矣，既可得而知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"何以知天之愛百姓也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"吾以賢者之必賞善罰暴也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 11,\n      \"canonicalText\": \"何以知賢者之必賞善罰暴也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 12,\n      \"canonicalText\": \"吾以昔者三代之聖王知之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 13,\n      \"canonicalText\": \"故昔也三代之聖王堯舜禹湯文武之兼愛天下也，從而利之，移其百姓之意焉，率以敬上帝山川鬼神，天以為從其所愛而愛之，從其所利而利之，於是加其賞焉，使之處上位，立為天子以法也，名之曰『聖人』，以此知其賞善之證。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 14,\n      \"canonicalText\": \"是故昔也三代之暴王桀紂幽厲之兼惡天下也，從而賊之，移其百姓之意焉，率以詬侮上帝山川鬼神，天以為不從其所愛而惡之，不從其所利而賊之，於是加其罰焉，使之父子離散，國家滅亡，抎失社稷，憂以及其身。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 15,\n      \"canonicalText\": \"是以天下之庶民屬而毀之，業萬世子孫繼嗣，毀之者不廢也，名之曰『暴王』，以此知其罰暴之證。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-4_s-16\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-4\",\n      \"order\": 16,\n      \"canonicalText\": \"今天下之士君子，欲為義者，則不可不順天之意矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"曰順天之意者，兼也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"反天之意者，別也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"兼之為道也，義正；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"別之為道也，力正。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"曰義正者何若？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"曰大不攻小也，強不侮弱也，眾不賊寡也，詐不欺愚也，貴不傲賤也，富不驕貧也，壯不奪老也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"是以天下之庶國，莫以水火毒藥兵刃以相害也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"若事上利天，中利鬼，下利人，三利而無所不利，是謂天德。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"故凡從事此者，聖知也，仁義也，忠惠也，慈孝也，是故聚斂天下之善名而加之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"是其故何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 11,\n      \"canonicalText\": \"則順天之意也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 12,\n      \"canonicalText\": \"曰力正者何若？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 13,\n      \"canonicalText\": \"曰大則攻小也，強則侮弱也，眾則賊寡也，詐則欺愚也，貴則傲賤也，富則驕貧也，壯則奪老也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 14,\n      \"canonicalText\": \"是以天下之庶國，方以水火毒藥兵刃以相賊害也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 15,\n      \"canonicalText\": \"若事上不利天，中不利鬼，下不利人，三不利而無所利，是謂天賊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-16\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 16,\n      \"canonicalText\": \"故凡從事此者，寇亂也，盜賊也，不仁不義，不忠不惠，不慈不孝，是故聚斂天下之惡名而加之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-17\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 17,\n      \"canonicalText\": \"是其故何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-18\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 18,\n      \"canonicalText\": \"則反天之意也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-5_s-19\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-5\",\n      \"order\": 19,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"故子墨子置立天之，以為儀法，若輪人之有規，匠人之有矩也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"今輪人以規，匠人以矩，以此知方圜之別矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"是故子墨子置立天之，以為儀法。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"吾以此知天下之士君子之去義遠也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"何以知天下之士君子之去義遠也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"今知氏大國之君寬者然曰：「吾處大國而不攻小國，吾何以為大哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"」是以差論蚤牙之士，比列其舟車之卒，以攻伐無罪之國，入其邊境，刈其禾稼，斬其樹木，殘其城郭，以湮其溝池，焚燒其祖廟，攘殺其犧牷，民之格者，則剄殺之，不格者，則係操而歸，丈夫以為僕圉胥靡，婦人以為舂酋。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"則夫好攻伐之君，不知此為不仁義，以告四鄰諸侯曰：「吾攻國覆軍，殺將若干人矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"」其鄰國之君亦不知此為不仁義也，有具其皮幣，發其總處，使人饗賀焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"則夫好攻伐之君，有重不知此為不仁不義也，有書之竹帛，藏之府庫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"為人後子者，必且欲順其先君之行，曰：「何不當發吾府庫，視吾先君之法美。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"」必不曰文、武之為正者若此矣，曰吾攻國覆軍殺將若干人矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-6_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-6\",\n      \"order\": 13,\n      \"canonicalText\": \"則夫好攻伐之君，不知此為不仁不義也，其鄰國之君不知此為不仁不義也，是以攻伐世世而不已者，此吾所謂大物則不知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"所謂小物則知之者何若？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"今有人於此，入人之場園，取人之桃李瓜薑者，上得且罰之，眾聞則非之，是何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"曰不與其勞，獲其實，已非其有所取之故，而況有踰於人之牆垣，抯格人之子女者乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"與角人之府庫，竊人之金玉蚤絫者乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"與踰人之欄牢，竊人之牛馬者乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"而況有殺一不辜人乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"今王公大人之為政也，自殺一不辜人者；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"踰人之牆垣，抯格人之子女者；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 9,\n      \"canonicalText\": \"與角人之府庫，竊人之金玉蚤絫者乎；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 10,\n      \"canonicalText\": \"與踰人之欄牢，竊人之牛馬者；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 11,\n      \"canonicalText\": \"與入人之場園，竊人之桃李瓜薑者，今王公大人之加罰此也，雖古之堯舜禹湯文武之為政，亦無以異此矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 12,\n      \"canonicalText\": \"今天下之諸侯，將猶皆侵凌攻伐兼併，此為殺一不辜人者，數千萬矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 13,\n      \"canonicalText\": \"此為踰人之牆垣，格人之子女者，與角人府庫，竊人金玉蚤絫者，數千萬矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 14,\n      \"canonicalText\": \"踰人之欄牢，竊人之牛馬者，與入人之場園，竊人之桃李瓜薑者，數千萬矣，而自曰義也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 15,\n      \"canonicalText\": \"故子墨子言曰：「是蕡我者，則豈有以異是蕡黑白甘苦之辯者哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-16\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 16,\n      \"canonicalText\": \"今有人於此，少而示之黑謂之黑，多示之黑謂白，必曰吾目亂，不知黑白之別。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-17\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 17,\n      \"canonicalText\": \"今有人於此，能少嘗之甘謂甘，多嘗謂苦，必曰吾口亂，不知其甘苦之味。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-18\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 18,\n      \"canonicalText\": \"今王公大人之政也，或殺人，其國家禁之，此蚤越有能多殺其鄰國之人，因以為文義，此豈有異蕡白黑、甘苦之別者哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-7_s-19\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-7\",\n      \"order\": 19,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-8_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"故子墨子置天之，以為儀法。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-8_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"非獨子墨子以天之志為法也，於先王之書大夏之道之然：「帝謂文王，予懷而明德，毋大聲以色，毋長夏以革，不識不知，順帝之則。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-8_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"」此誥文王之以天志為法也，而順帝之則也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-8_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"且今天下之士君子，中實將欲為仁義，求為上士，上欲中聖王之道，下欲中國家百姓之利者，當天之志，而不可不察也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-28_p-8_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-28\",\n      \"passageId\": \"mo-zi_ch-28_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"天之志者，義之經也。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
